package com.yourorg.golden.request;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Duration;
import java.time.Instant;
import org.junit.jupiter.api.Test;

class SlaPolicyTest {

    private static final Instant CREATED = Instant.parse("2026-01-01T09:00:00Z");

    @Test
    void dueDateIsCreatedAtPlusTheCategoryWindow() {
        assertThat(SlaPolicy.dueDate(Category.TECHNICAL, CREATED)).isEqualTo(CREATED.plus(Duration.ofHours(4)));
        assertThat(SlaPolicy.dueDate(Category.BILLING, CREATED)).isEqualTo(CREATED.plus(Duration.ofHours(24)));
        assertThat(SlaPolicy.dueDate(Category.ACCOUNT, CREATED)).isEqualTo(CREATED.plus(Duration.ofHours(48)));
        assertThat(SlaPolicy.dueDate(Category.OTHER, CREATED)).isEqualTo(CREATED.plus(Duration.ofHours(72)));
    }

    @Test
    void breachedIsTrueOnlyStrictlyPastTheDueDate() {
        var due = SlaPolicy.dueDate(Category.TECHNICAL, CREATED);
        assertThat(SlaPolicy.isBreached(Category.TECHNICAL, CREATED, due.minusSeconds(1))).isFalse();
        assertThat(SlaPolicy.isBreached(Category.TECHNICAL, CREATED, due)).isFalse();
        assertThat(SlaPolicy.isBreached(Category.TECHNICAL, CREATED, due.plusSeconds(1))).isTrue();
    }
}
